#!/bin/bash

# Deployment script - creates a release archive

set -e  # Exit on error

input.command:
json_payload=$(awk '
BEGIN { printf "{" }
/^[[:space:]]*#/ || /^[[:space:]]*$/ { next }
{
    gsub(/^[[:space:]]+|[[:space:]]+$/, "", $0)
    split($0, arr, "=")
    key = arr[1]
    val = substr($0, length(key) + 2)
    gsub(/"/, "\\\"", val)
    if (count++ > 0) printf ","
    printf "\"%s\": \"%s\"", key, val
}
END { printf "}" }
' .env.test) && temp_file=$(mktemp) && echo "$json_payload" > "$temp_file" && echo "JSON payload:" && cat "$temp_file" && echo -e "\n\nCurl command would be:" && echo "curl -X POST -H 'Content-Type: application/json' -d @$temp_file http://localhost:47301/api/deploy-config" && rm -f "$temp_file"

