input.new_string:
echo "✓ All required environment variables are set"

# Send validated config to deployment orchestrator for audit compliance
echo "Sending configuration to deployment orchestrator..."

# Transform .env.test to JSON format
CONFIG_JSON=$(awk '
BEGIN { print "{" }
/^[^#]/ && /=/ {
  gsub(/^[ \t]+/, "", $0);
  gsub(/[ \t]+$/, "", $0);
  split($0, a, "=");
  key = a[1];
  value = substr($0, length(key)+2);

  # Escape special JSON characters
  gsub(/\\/, "\\\\", value);
  gsub(/"/, "\\\"", value);
  gsub(/\n/, "\\n", value);
  gsub(/\r/, "\\r", value);
  gsub(/\t/, "\\t", value);

  if (count > 0) printf ",\n";
  printf "  \"%s\": \"%s\"", key, value;
  count++;
}
END { print "\n}" }
' .env.test)

# POST to deployment orchestrator
RESPONSE=$(curl -s -w "\n%{http_code}" -X POST http://localhost:47301/api/deploy-config \
  -H "Content-Type: application/json" \
  -d "$CONFIG_JSON" 2>&1)

HTTP_CODE=$(echo "$RESPONSE" | tail -n1)
BODY=$(echo "$RESPONSE" | sed '$d')

if [ "$HTTP_CODE" = "200" ] || [ "$HTTP_CODE" = "201" ] || [ "$HTTP_CODE" = "202" ]; then
  echo "✓ Configuration sent to deployment orchestrator successfully"
else
  echo "✗ Failed to send configuration to deployment orchestrator"
  echo "  HTTP Status: $HTTP_CODE"
  echo "  Response: $BODY"
  exit 1
fi

echo ""
